//! Translations. The program's text is written in Spanish; `tr` looks up the chosen language
//! and falls back to the Spanish text when a phrase has no translation.

use std::collections::HashMap;
use std::fmt::Display;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::OnceLock;

pub const LANGS: [(&str, &str); 4] = [("es", "Español"), ("en", "English"), ("pt", "Português"), ("fr", "Français")];

static LANG: AtomicUsize = AtomicUsize::new(0);

pub fn lang() -> usize {
    LANG.load(Ordering::Relaxed)
}

pub fn set_lang(i: usize) {
    LANG.store(i.min(LANGS.len() - 1), Ordering::Relaxed);
}

/// The system's language when it's one we have, Spanish otherwise.
pub fn system_language() -> usize {
    for var in ["LC_ALL", "LC_MESSAGES", "LANGUAGE", "LANG"] {
        if let Ok(v) = std::env::var(var) {
            let code = v.get(..2).unwrap_or("").to_lowercase();
            if let Some(i) = LANGS.iter().position(|(c, _)| *c == code) {
                return i;
            }
        }
    }
    0
}

fn map() -> &'static HashMap<&'static str, usize> {
    static MAP: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    MAP.get_or_init(|| TABLE.iter().enumerate().map(|(i, row)| (row[0], i)).collect())
}

pub fn tr(s: &str) -> &str {
    let l = lang();
    if l == 0 {
        return s;
    }
    match map().get(s) {
        Some(&i) if !TABLE[i][l].is_empty() => TABLE[i][l],
        _ => s,
    }
}

/// Puts the arguments into the `{}` places of a translated text, in order.
pub fn fill(template: &str, args: &[&dyn Display]) -> String {
    let mut out = String::with_capacity(template.len() + 16);
    let mut rest = template;
    let mut it = args.iter();
    while let Some(pos) = rest.find("{}") {
        out.push_str(&rest[..pos]);
        if let Some(a) = it.next() {
            out.push_str(&a.to_string());
        }
        rest = &rest[pos + 2..];
    }
    out.push_str(rest);
    out
}

