#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn no_duplicate_keys_and_placeholders_match() {
        let mut seen = std::collections::HashSet::new();
        for row in TABLE {
            assert!(seen.insert(row[0]), "repetida: {}", row[0]);
            let n = row[0].matches("{}").count();
            for t in &row[1..] {
                assert_eq!(t.matches("{}").count(), n, "{} / {}", row[0], t);
            }
        }
    }

    #[test]
    fn fills_in_order() {
        assert_eq!(fill("{} de {}", &[&1, &"x"]), "1 de x");
    }
}
